// 1. 先计算总服务费，作为基础数据
VAR TotalOffer_ = 
    SUMX(
        FILTER(
            '2.0 CC_offer数据切分前后',
            '2.0 CC_offer数据切分前后'[income_rn（计算offer数据，限制rn=1)] = 1 
        ),
        '2.0 CC_offer数据切分前后'[分成后服务费_不含税] 
    )

// 2. 如果没有基础数据（结果为空），直接返回空值，避免视觉对象显示为 0
VAR HasData = NOT ISBLANK(TotalOffer_)

// 3. 获取单位，如果匹配不到则返回空值（而不是默认返回 1，防止计算偏差）
VAR Unit_ = SELECTEDVALUE('00 动态单位表'[度量])

RETURN
    IF(
        HasData && NOT ISBLANK(Unit_), 
        DIVIDE(TotalOffer_, Unit_), 
        BLANK() 
    )

CALCULATE(
    SUM('1.0 Namelist'[HC]),
    '1.0 Namelist'[雇佣类型] IN { "全职", "正式（全职）" }
)
